def game_winner(n):
    if n % 3 == 0:
        return "First"
    elif n % 10 == 0:
        return "Second"
    else:
        return "First"
for t in range(1, 101):
    n = int(input())
    print(f"Case #{t}: {game_winner(n)}")

def max_sum_subarray(n, arr):
    max_sum = 0
    for i in range(n):
        for j in range(i+1, n):
            if arr[i] == arr[j]:
                max_sum += arr[i]
            else:
                max_sum += abs(arr[i] - arr[j])
    return max_sum

def count_pairs(n, a):
    count = 0
    for i in range(1, n):
        for j in range(i+1, n):
            if a[i]**a[j] == a[j]**a[i]:
                count += 1
    return count

def count_over_60(details):
    count = 0
    for i in range(len(details)):
        if details[i][10] == 'M' or details[i][10] == 'F' or details[i][10] == 'O':
            if int(details[i][11:]) > 60:
                count += 1
    return count

def max_score(nums):
    score = 0
    for row in nums:
        max_num = max(row)
        for num in row:
            if num == max_num:
                score += num
                break
    return score

def max_product_after_k_operations(nums, k):
    max_product = 0
    for i in range(len(nums)):
        for j in range(k):
            nums[i] = nums[i] * 2
            max_product = max(max_product, nums[i])
    return max_product

def maxStrengthGroup(nums):
    max_strength = 0
    max_group = []

    for i in range(len(nums)):
        group_strength = 1
        for j in range(i+1, len(nums)):
            group_strength *= nums[j]

        if group_strength > max_strength:
            max_strength = group_strength
            max_group = [i]
        elif group_strength == max_strength:
            max_group.append(i)

    return max_strength

def min_extra_chars(s, dictionary):
    # Create a dictionary to store the frequency of each character
    char_freq = {}
    for word in dictionary:
        char_freq[word[0]] = char_freq.get(word[0], 0) + 1

    # Create a dictionary to store the frequency of each character in s
    s_freq = {}
    for char in s:
        s_freq[char] = s_freq.get(char, 0) + 1

    # Initialize a variable to store the minimum extra characters
    min_extra_chars = 0

    # Iterate over each character in s
    for char in s:
        # If the character is not present in any of the substrings, add it to the minimum extra characters
        if char not in s_freq:
            min_extra_chars += 1

    return min_extra_chars

def distinctDifference(nums):
    diff = [0] * len(nums)
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            diff[i] += nums[i] - nums[j]
    return diff

