def longest_semi_repetitive_substring(s):
    # Create a dictionary to store the count of each digit
    count_dict = {}
    for i in range(len(s)):
        count_dict[s[i]] = count_dict.get(s[i], 0) + 1

    # Initialize max_length to 0
    max_length = 0

    # Iterate through the string
    for i in range(len(s)):
        # If the current character is not in the dictionary, it means it is the first occurrence of the digit
        if s[i] not in count_dict:
            # If the current character is the first occurrence of the digit, we can start a new semi-repetitive substring
            if count_dict[s[i]] == 1:
                max_length = max(max_length, i - count_dict[s[i]] + 1)
            # If the current character is not the first occurrence of the digit, we can extend the current semi-repetitive substring
            else:
                max_length = max(max_length, i - count_dict[s[i]] + 1)

    return max_length

def losers(n, k):
    # Generate the game sequence
    sequence = [1] * n
    for i in range(1, n):
        for j in range(i, n):
            sequence[i] = sequence[i] + sequence[j]
            sequence[j] = sequence[j] + sequence[i]

    # Find the losers
    losers = [i for i in range(n) if sequence[i] == sequence[i] + k]

    return losers

def isValid(derived):
    n = len(derived)
    for i in range(n):
        if derived[i] == derived[i+1] ^ derived[i+1] == derived[i]:
            return True
    return False

def minCostPaint(cost, time):
    n = len(cost)
    dp = [[0]*n for _ in range(n+1)]

    for i in range(n+1):
        for j in range(i+1, n+1):
            dp[i][j] = min(dp[i][j], dp[i-1][j-1] + cost[i-1] + time[j-1])

    return dp[n][n]

def minSumKAvoidingArray(n, k):
    # Create a list of all possible k-avoiding arrays of length n
    k_avoiding_arrays = []
    for i in range(1, n+1):
        for j in range(i+1, n+1):
            if i + j == k:
                k_avoiding_arrays.append([i, j])

    # Find the minimum sum of all k-avoiding arrays
    min_sum = float('inf')
    for array in k_avoiding_arrays:
        sum_of_array = sum(array)
        if sum_of_array < min_sum:
            min_sum = sum_of_array

    return min_sum

def max_achievable(num, t):
    # Initialize the maximum achievable number to 0
    max_achievable = 0

    # Iterate over the range of possible values for x
    for x in range(num, num + t):
        # Check if x is achievable
        if x == num:
            # If x is achievable, update the maximum achievable number
            max_achievable = max(max_achievable, x)
        else:
            # If x is not achievable, update the maximum achievable number
            max_achievable = max(max_achievable, num - x)

    return max_achievable

def minCost(s):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        for j in range(i, n + 1):
            dp[i][j] = min(dp[i][j], dp[i - 1][j] + dp[i][j - 1])
    return dp[n][n]

def remove_trailing_zeros(num):
    num = int(num)
    while num % 10 == 0:
        num //= 10
    return str(num)

def isFascinating(n):
    # Concatenate n with 2 * n and 3 * n
    result = n + 2 * n + 3 * n

    # Check if the resulting number contains all digits from 1 to 9 exactly once and does not contain any 0's
    return all(int(digit) in range(1, 10) for digit in str(result))

def canVisitAllPairs(nums):
    n = len(nums)
    dp = [[False] * (n + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        for j in range(i + 1):
            if gcd(nums[i], nums[j]) > 1:
                dp[i][j] = dp[i][j - 1] or dp[i - 1][j]

    return dp[n][0]

def beautifulPairs(nums):
    count = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] % 10 == nums[j] % 10:
                count += 1
    return count

def longestSubarray(nums, k):
    n = len(nums)
    max_length = 0
    max_start = 0
    max_end = 0

    for i in range(n):
        for j in range(i+1, n):
            if nums[i] == nums[j]:
                max_length = max(max_length, j - i + 1)
                max_start = max(max_start, i)
                max_end = max(max_end, j)

                if max_length > k:
                    return max_length

    return max_length

def count_servers_without_requests(n, logs, x, queries):
    # Create a dictionary to store the servers that have received requests
    server_requests = {}

    # Iterate over the logs array
    for server_id, time in logs:
        # If the server has not received a request in the given time interval, add it to the dictionary
        if time >= queries[0] - x and time <= queries[1]:
            server_requests[server_id] = 1

    # Create an array to store the servers that did not receive any requests
    arr = [0] * len(queries)

    # Iterate over the queries array
    for i in range(len(queries)):
        # Iterate over the server_requests dictionary
        for server_id, _ in server_requests.items():
            # If the server has not received a request in the given time interval, add it to the array
            if time >= queries[i] - x and time <= queries[i]:
                arr[i] += 1

    return arr

def findOccupiedPositions(nums, moveFrom, moveTo):
    occupied = set()
    for i in range(len(nums)):
        occupied.add(nums[i])
    for i in range(len(moveFrom)):
        occupied.update(moveFrom[i])
    for i in range(len(moveTo)):
        occupied.update(moveTo[i])
    return sorted(occupied)

def max_sum_query(nums1, nums2, queries):
    n = len(nums1)
    max_sum = -1
    for i in range(n):
        for j in range(n):
            if nums1[i] >= queries[i][1] and nums2[j] >= queries[i][2]:
                if nums1[i] + nums2[j] > max_sum:
                    max_sum = nums1[i] + nums2[j]
    return [max_sum] * len(queries)

def sumOfSquaresOfSpecialElements(nums):
    special_elements = [num for num in nums if num % n == 0]
    return sum(i**2 for i in special_elements)

def minPartition(nums):
    n = len(nums)
    if n == 0:
        return 0

    max_nums1 = max(nums)
    min_nums2 = min(nums)

    for i in range(n):
        if nums[i] < max_nums1:
            max_nums1 = nums[i]
        if nums[i] > min_nums2:
            min_nums2 = nums[i]

    return abs(max_nums1 - min_nums2)

def maxPairs(words):
    # Create a dictionary to store the number of pairs for each word
    pair_count = {}

    # Iterate through the words
    for i in range(len(words)):
        # Check if the current word is already in the dictionary
        if words[i] in pair_count:
            # If it is, increment the count
            pair_count[words[i]] += 1
        else:
            # If it isn't, initialize the count to 1
            pair_count[words[i]] = 1

    # Find the maximum count
    max_count = max(pair_count.values())

    # Return the maximum number of pairs
    return max_count

def countSpecialPermutations(nums):
    # Create a dictionary to store the count of special permutations
    special_count = {}

    # Iterate over all possible permutations
    for perm in itertools.permutations(nums):
        # Check if the permutation is special
        if all(nums[i] % nums[i+1] == 0 or nums[i+1] % nums[i] == 0 for i in range(len(perm)-1)):
            special_count[perm] = special_count.get(perm, 0) + 1

    # Return the total number of special permutations
    return sum(special_count.values()) % 10**9 + 7

def sum_imbalance_numbers(nums):
    n = len(nums)
    imbalance_numbers = [0] * n
    for i in range(n):
        sorted_arr = sorted(nums[i:])
        for j in range(i+1, len(sorted_arr)):
            if sorted_arr[j] - sorted_arr[i] > 1:
                imbalance_numbers[i] += 1
    return sum(imbalance_numbers)

def min_join_length(words):
    n = len(words)
    str_0 = words[0]
    str_1 = ""
    for i in range(1, n):
        if i == n - 1:
            str_1 = join(str_1, words[i])
        else:
            str_1 = join(words[i], str_1)
    return len(str_1)

def maxJumps(nums, target):
    n = len(nums)
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(i):
            if nums[j] - nums[i] == target:
                dp[i] = max(dp[i], dp[j] + 1)
    return dp[n]

def countCompleteSubarrays(nums):
    n = len(nums)
    complete_subarrays = 0
    for i in range(n):
        for j in range(i+1, n):
            if nums[i] == nums[j]:
                complete_subarrays += 1
    return complete_subarrays

def longestSubarray(nums, threshold):
    n = len(nums)
    max_length = 0
    max_start = 0
    max_end = 0

    for i in range(n):
        if nums[i] % 2 == 0:
            if nums[i] <= threshold:
                max_length = max(max_length, i - max_start + 1)
                max_start = i
                max_end = i
        else:
            if nums[i] <= threshold:
                max_length = max(max_length, i - max_start + 1)
                max_start = i
                max_end = i

    return max_length

def countGoodSubarrays(nums):
    count = 0
    for i in range(len(nums)):
        if nums[i] == 1:
            count += 1
    return count % (10**9 + 7)

def countContinuousSubarrays(nums):
    count = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if abs(nums[i] - nums[j]) <= 2:
                count += 1
    return count

def maxSubArray(nums1, nums2):
    n = len(nums1)
    nums3 = [nums1[0], nums2[0]]
    for i in range(1, n):
        nums3.append(max(nums1[i], nums2[i]))
    return len(nums3)

def max_alternating_subarrays(nums):
    max_length = 0
    for i in range(len(nums)):
        if nums[i] % 2 == 1:
            max_length = max(max_length, i - nums[i] // 2 + 1)
    return max_length

def max_element(nums):
    max_val = nums[0]
    for i in range(1, len(nums)):
        if nums[i] > max_val:
            max_val = nums[i]
    return max_val

def generate_prime_pairs(n):
    prime_pairs = []
    for x in range(1, n):
        for y in range(x, n):
            if x + y == n and x % 2 == 0 and y % 2 == 0:
                prime_pairs.append([x, y])
    prime_pairs.sort(key=lambda x: x[0])
    return prime_pairs

def count_employees(hours, target):
    count = 0
    for i in range(len(hours)):
        if hours[i] >= target:
            count += 1
    return count

def find_min_string(a, b, c):
    # Create a dictionary to store the frequency of each character
    char_freq = {}

    # Count the frequency of each character in the strings a, b, and c
    for char in a:
        char_freq[char] = char_freq.get(char, 0) + 1
    for char in b:
        char_freq[char] = char_freq.get(char, 0) + 1
    for char in c:
        char_freq[char] = char_freq.get(char, 0) + 1

    # Find the minimum length string that contains all three strings as substrings
    min_len = float('inf')
    min_string = ''

    for i in range(len(a)):
        for j in range(len(b)):
            for k in range(len(c)):
                if a[i:i+j] in char_freq and b[j:j+k] in char_freq and c[k:k+1] in char_freq:
                    if len(min_string) + j + k < min_len:
                        min_len = len(min_string) + j + k
                        min_string = a[i:i+j] + b[j:j+k] + c[k:k+1]

    return min_string

def can_make_all_elements_zero(nums, k):
    for i in range(len(nums)):
        if nums[i] > 0:
            nums[i] -= 1
            if all(nums[j] == 0 for j in range(i, len(nums))):
                return True
    return False

def min_letter_changes(s, k):
    # Create a dictionary to store the number of changes required for each substring
    changes = {}

    # Iterate through the string
    for i in range(len(s)):
        # Check if the substring starting at index i is a palindrome
        if s[i:i+k] == s[i:i+k][::-1]:
            # If it is, add 1 to the count for the substring
            changes[s[i:i+k]] = 1

    # Return the minimum number of changes
    return min(changes.values())

def split_words(words, separator):
    result = []
    for word in words:
        if word:
            result.append(word.split(separator)[0])
    return result

def longestValidSubstring(word, forbidden):
    # Create a dictionary to store the frequency of each character
    char_freq = {}
    for char in word:
        char_freq[char] = char_freq.get(char, 0) + 1

    # Create a dictionary to store the frequency of each character in forbidden
    forbidden_freq = {}
    for char in forbidden:
        forbidden_freq[char] = forbidden_freq.get(char, 0) + 1

    # Initialize the longest valid substring length
    max_length = 0

    # Iterate through each character in word
    for char in word:
        # Check if the character is in forbidden
        if char in forbidden_freq:
            # If the character is in forbidden, increment the length of the longest valid substring
            max_length = max(max_length, char_freq[char] - forbidden_freq[char])

    return max_length

def reverse_string(s):
    # Create a new string with the characters of the original string
    reversed_string = ""
    for char in s:
        # If the character is an 'i', reverse the string
        if char == 'i':
            reversed_string = reversed_string[::-1]
        # Otherwise, append the character to the string
        else:
            reversed_string += char
    return reversed_string

def permute_string(s):
    vowels = 'aeiou'
    vowels_index = vowels.index('a')

    def swap_vowels(i, j):
        if i < j:
            temp = s[i]
            s[i] = s[j]
            s[j] = temp

    def sort_vowels(i, j):
        if i < j:
            if s[i] in vowels and s[j] in vowels:
                if s[i] < s[j]:
                    temp = s[i]
                    s[i] = s[j]
                    s[j] = temp
                else:
                    temp = s[j]
                    s[j] = s[i]
                    s[i] = temp
            else:
                if s[i] in vowels:
                    temp = s[i]
                    s[i] = s[j]
                    s[j] = temp
                else:
                    temp = s[j]
                    s[j] = s[i]
                    s[i] = temp

    for i in range(len(s)):
        if s[i] in vowels:
            sort_vowels(i, i)
        else:
            swap_vowels(i, i)

    return ''.join(s)

def maxBeauty(nums, k):
    max_beauty = 0
    for i in range(len(nums)):
        if i == 0:
            max_beauty = max(max_beauty, nums[i])
        else:
            max_beauty = max(max_beauty, nums[i] - k)
    return max_beauty

def isGood(nums):
    n = max(nums)
    base = [1, 2, ..., n - 1, n, n]
    for i in range(len(nums)):
        if nums[i] not in base[i]:
            return False
    return True

def maxScore(nums, x):
    max_score = 0
    for i in range(len(nums)):
        score = nums[i]
        for j in range(i + 1, len(nums)):
            if nums[j] != nums[i]:
                score -= x
        max_score = max(max_score, score)
    return max_score

def max_pair_sum(nums):
    max_sum = -1
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] + nums[j] > max_sum:
                max_sum = nums[i] + nums[j]
    return max_sum

def count_interesting_subarrays(nums, modulo, k):
    interesting_count = 0
    for i in range(len(nums)):
        if nums[i] % modulo == k:
            interesting_count += 1
    return interesting_count

def canSplitArray(nums, m):
    n = len(nums)
    dp = [[False] * (m + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        for j in range(i + 1, n + 1):
            if dp[i][j] == True:
                dp[i][j] = dp[i - 1][j - 1] or dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]

    return dp[n][m]

def countPairs(nums, target):
    count = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] < target:
                count += 1
    return count

def createGroups(usageLimits):
    groups = []
    group = []

    for i in range(len(usageLimits)):
        if usageLimits[i] > 0:
            group.append(usageLimits[i])
            if len(group) > 1:
                groups.append(group)
                group = []
            usageLimits[i] -= 1

    if len(group) > 0:
        groups.append(group)

    return len(groups)

def count_stepping_numbers(low, high):
    # Convert the input strings to integers
    low_int = int(low)
    high_int = int(high)

    # Initialize the count of stepping numbers
    count = 0

    # Iterate over the range [low, high]
    for i in range(low_int, high_int + 1):
        # Check if the number is a stepping number
        if abs(i % 10 - i // 10) == 1:
            count += 1

    # Return the count modulo 10^9 + 7
    return count % (10**9 + 7)

def minTime(nums1, nums2, x):
    n = len(nums1)
    for i in range(n):
        nums1[i] += nums2[i]
    for i in range(n):
        nums1[i] = 0

    for i in range(n):
        if nums1[i] > x:
            return -1

    return sum(nums1)

def countPairs(coordinates, k):
    # Initialize a dictionary to store the number of pairs
    pairs = {}

    # Iterate through the coordinates
    for i in range(len(coordinates)):
        for j in range(i + 1, len(coordinates)):
            # Calculate the distance between the points
            distance = (coordinates[i][0] ^ coordinates[j][0]) + (coordinates[i][1] ^ coordinates[j][1])
            # If the distance is equal to k, add 1 to the pairs count
            if distance == k:
                pairs[i, j] = pairs.get(i, 0) + pairs.get(j, 0) + 1

    return pairs.values()

def max_sum_almost_unique_subarrays(nums, m, k):
