    # Initialize the distance matrix
    distances = [[0] * N for _ in range(N)]

    # Initialize the infected status
    infected = [False] * N

    # Calculate the distance matrix
    for i in range(N):
        for j in range(N):
            if i != j:
                distances[i][j] = dist(X[i], Y[i], X[j], Y[j])

    # Check if all people within a distance of D from person i are infected
    for i in range(N):
        if distances[i][i] == D:
            infected[i] = True

    return infected

