def find_cookie_square(grid):
    # Initialize the grid
    grid = [["." for _ in range(W)] for _ in range(H)]

    # Initialize the visited grid
    visited = [[False for _ in range(W)] for _ in range(H)]

    # Initialize the visited grid
    visited[0][0] = True

    # Iterate through the grid
    for i in range(1, H):
        for j in range(1, W):
            if grid[i-1][j-1] == "#":
                # If the current square is not visited and the current square is not empty,
                # then the current square is the cookie square
                if not visited[i-1][j-1] and grid[i-1][j-1] != ".":
                    return (i-1, j-1)

    # If the current square is not visited and the current square is not empty,
    # then the current square is the cookie square
    return None

