                distances[a_i][b_j] = min(distances[a_i][b_j], distances[b_i][a_j] + h[i])

        # If the distance is less than or equal to h_i, add the vertex to the guard list
        if distances[a_i][b_i] <= h[i]:
            guard_list.append(a_i)

    # Sort the guard list in ascending order
    guard_list.sort()

    return len(guard_list), guard_list

