def min_operations(N):
    # Create a dictionary to store the minimum number of operations for each vertex
    operations = {vertex: float('inf') for vertex in range(N + 1)}

    # Initialize the minimum number of operations for each vertex
    for vertex in range(N + 1):
        operations[vertex] = 0

    # Perform the operations
    for vertex in range(N + 1):
        for u in range(N + 1):
            for v in range(N + 1):
                if u != v and u != vertex and v != vertex:
                    operations[vertex] = min(operations[vertex], operations[u] + operations[v])

    # Return the minimum number of operations
    return min(operations.values())

