    min_operations = -1

    # Initialize the grid
    grid = [["." for _ in range(W)] for _ in range(H)]

    # Fill the grid with the given strings
    for i in range(H):
        for j in range(W):
            grid[i][j] = S_i[j]

    # Perform the operations
    for _ in range(K):
        # Choose one cell with the character '.' and change the character in that cell to 'o'
        for i in range(H):
            for j in range(W):
                if grid[i][j] == '.':
                    grid[i][j] = 'o'
                    min_operations = min(min_operations, 1)
                    break

    # Check if it is possible to have a sequence of K horizontally or vertically consecutive cells with o written in all cells
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'o':
                # Check if it is possible to have a sequence of K horizontally or vertically consecutive cells with o written in all cells
                if (i, j) in ((i, j+1) for i in range(H) for j in range(W-K+1) if grid[i][j] == 'o'):
