def findIncrease(nums1, nums2):
    # Check if the arrays are equal
    if nums1 == nums2:
        return 0

    # Initialize the increase value
    increase = 0

    # Iterate through the arrays
    for i in range(len(nums1)):
        # If the current element in nums1 is greater than nums2[i], increase the increase value
        if nums1[i] > nums2[i]:
            increase += 1

        # If the current element in nums1 is less than nums2[i], decrease the increase value
        elif nums1[i] < nums2[i]:
            increase -= 1

    # Return the increase value
    return increase

