def isValidWord(word):
    # Check if the word is empty
    if not word:
        return False

    # Check if the word contains at least 3 characters
    if len(word) < 3:
        return False

    # Check if the word contains only digits and English letters
    if not all(char.isdigit() or char.isalpha() for char in word):
        return False

    # Check if the word contains at least one vowel
    if not any(char.lower() in 'aeiou' for char in word):
        return False

    # Check if the word contains at least one consonant
    if not any(char.lower() not in 'aeiou' for char in word):
        return False

    return True

def minOperations(word, k):
    # Create a dictionary to store the minimum operations for each length of k
    operations = {}
    for i in range(1, len(word) + 1):
        for j in range(i, len(word) + 1):
            if i % k == j % k:
                operations[(i, j)] = operations.get((i, j), 0) + 1

    # Find the minimum operations for k-periodicity
    min_operations = float('inf')
    for i in range(1, len(word) + 1):
        for j in range(i, len(word) + 1):
            if i % k == j % k:
                if operations[(i, j)] < min_operations:
                    min_operations = operations[(i, j)]

    return min_operations

def minAnagramLength(s):
    # Create a dictionary to store the frequency of each character
    char_freq = {}

    # Count the frequency of each character
    for char in s:
        char_freq[char] = char_freq.get(char, 0) + 1

    # Find the minimum length of t such that t is an anagram of s
    min_length = float('inf')
    for i in range(len(s)):
        for j in range(i + 1, len(s)):
            if s[i] == s[j]:
                freq_i = char_freq[s[i]]
                freq_j = char_freq[s[j]]
                if freq_i > freq_j:
                    min_length = min(min_length, i - j + 1)

    return min_length

def minCost(nums, cost1, cost2):
    # Create a dictionary to store the minimum cost for each index
    min_cost = {}

    # Iterate over the array
    for i in range(len(nums)):
        # If the current index is not in the dictionary, initialize it with the current value
        if i not in min_cost:
            min_cost[i] = nums[i]
        # If the current index is in the dictionary, update the minimum cost
        else:
            min_cost[i] = min(min_cost[i], nums[i] + cost1)

    # Iterate over the array again
    for i in range(len(nums)):
        # If the current index is not in the dictionary, initialize it with the current value
        if i not in min_cost:
            min_cost[i] = nums[i]
        # If the current index is in the dictionary, update the minimum cost
        else:
            min_cost[i] = min(min_cost[i], nums[i] + cost2)

    # Return the minimum cost modulo 10^9 + 7
    return min_cost[min(min_cost.keys())] % (10**9 + 7)

def can_create_square(grid):
