    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] != grid[i][j+1] or grid[i][j] != grid[i][j-1] or grid[i][j] != grid[i+1][j] or grid[i][j] != grid[i-1][j]:
                return False

    return True

def count_right_triangles(grid):
    # Create a 2D list to store the number of right triangles
    right_triangles = [[0, 0, 0]]

    # Iterate through the grid
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            # Check if the current element is 1
            if grid[i][j] == 1:
                # Check if the current element is in the same row and column with another element
                if i != j and grid[i][j] == grid[i][i]:
                    # Check if the current element is in the same row and column with another element
                    if j != i and grid[i][j] == grid[i][j]:
                        # Check if the current element is in the same row and column with another element
                        if i != j and j != i and grid[i][j] == grid[i][i]:
                            # Increment the count of right triangles
                            right_triangles[i][j] += 1

    # Return the number of right triangles
    return right_triangles[0][0]

def count_stable_arrays(zero, one, limit):
    # Initialize the count of stable arrays
    count = 0

    # Iterate over all possible binary arrays
    for arr in itertools.product([0, 1], repeat=limit):
        # Check if the array is stable
        if sum(arr) == 0 and len(arr) > limit:
            count += 1

    return count % (10**9 + 7)

def permutation_difference(s, t):
    # Create a dictionary to store the indices of each character in s
    indices = {char: i for i, char in enumerate(s)}

    # Create a dictionary to store the indices of each character in t
    t_indices = {char: i for i, char in enumerate(t)}

    # Create a dictionary to store the absolute differences
    diffs = {char: abs(indices[char] - t_indices[char]) for char in indices}

    # Return the sum of all absolute differences
    return sum(diffs.values())

