def partition(s):
    # Create a dictionary to store the count of each character
    char_count = {}

    # Count the occurrences of each character
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    # Initialize a list to store the balanced substrings
    balanced_substrings = []

    # Iterate through the characters in the string
    for char in s:
        # If the character is not in the dictionary, it's a new character
        if char not in char_count:
            # Add the character to the balanced substrings list
            balanced_substrings.append(char)
        # If the character is in the dictionary, it's a part of a balanced substring
        else:
            # If the character is the last character in the substring, add it to the balanced substrings list
            if char == s[len(s) - 1]:
                balanced_substrings.append(char)
            # If the character is not the last character in the substring, add it to the balanced substrings list
            else:
                balanced_substrings.append(char)

    # Return the minimum number of substrings
    return len(balanced_substrings)

