def big_nums(n):
    return [1] * n + [2] * (n - 1) + [8] * (n - 2)

def query(queries):
    result = []
    for i in range(len(queries)):
        from_i, to_i, mod_i = queries[i]
        from_i = from_i - 1
        to_i = to_i - 1
        mod_i = mod_i - 1
        product = big_nums(from_i) * big_nums(from_i + 1) * big_nums(from_i + 2)
        result.append(product % mod_i)
    return result

def answer(queries):
    return query(queries)

def find_xor_of_twice(nums):
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    xor_result = 0
    for num in nums:
        if num in count:
            xor_result ^= num

    return xor_result

